INSERT INTO madevi.articles (id, business_code, title, slug, summary, status, language, attribution_type, taxonomy_node_id, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah yang Sering Terjadi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$WiFi terasa lambat padahal sudah berlangganan paket internet cepat: video buffering terus, game ngelag, unduhan merangkak, dan halaman web lama terbuka. Banyak orang langsung menyalahkan penyedia internet, padahal penyebabnya sering ada di rumah sendiri — posisi router yang salah, terlalu banyak perangkat, atau kanal WiFi yang bertabrakan dengan tetangga. Artikel ini membantu kamu mendiagnosis akar masalahnya secara sistematis sebelum menghubungi teknisi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Dari Mana Koneksi Melambat$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kecepatan internet yang kamu bayar adalah kecepatan dari modem ke penyedia layanan. Tapi kecepatan yang kamu rasakan adalah kecepatan dari router ke perangkatmu melalui udara. Sinyal WiFi melemah menembus dinding dan beton, terganggu gelombang microwave atau Bluetooth, dan berebut kanal dengan jaringan tetangga. Jadi diagnosis berarti memisahkan: masalahnya di jalur internet (provider) atau di jalur WiFi (rumahmu).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan dan Langkah 1: Tes Kecepatan di Dekat Router$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$li$Siapkan HP atau laptop, lalu dekatkan ke router (jarak 1-2 meter, tanpa dinding).$li$, $li$Matikan unduhan dan aplikasi lain, buka situs tes kecepatan, catat hasilnya. Ulangi 3 kali dan ambil rata-rata.$li$, $li$Bandingkan dengan kecepatan paket langgananmu: jika jauh di bawah (misalnya paket 50 Mbps tapi hanya 10 Mbps) padahal di dekat router, masalahnya ada di modem/provider atau router. Jika normal di dekat router tapi lemot di kamar, masalahnya di jangkauan sinyal.$li$, $li$Opsional: bandingkan dengan kabel LAN untuk memastikan.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah 2 dan 3: Posisi Router dan Kanal WiFi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Langkah 2 — perbaiki posisi router: letakkan di tengah rumah, di tempat tinggi (rak, bukan lantai), tidak terkurung di dalam lemari atau di balik TV, dan jauh dari microwave serta dinding beton tebal. Antena tegak untuk penyebaran horizontal; jika rumah dua lantai, miringkan satu antena. Langkah 3 — pindah ke kanal yang sepi: unduh aplikasi analisis WiFi gratis (mis. WiFi Analyzer) dan lihat kanal yang dipakai jaringan sekitar. Jika banyak tetangga memakai kanal yang sama (misalnya kanal 6 di 2,4 GHz), pindahlah ke kanal paling sepi di antara 1, 6, atau 11 lewat halaman admin router (biasanya 192.168.1.1). Setelah keduanya, ulangi tes kecepatan di lokasi yang bermasalah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Hal yang Perlu Diperhatikan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Jangan sembarangan me-reset router ke setelan pabrik tanpa mencatat nama dan kata sandi WiFi serta data login provider — kamu bisa kehilangan koneksi total.$li$, $li$Hati-hati mengubah setelan lanjutan (DNS, firmware) jika tidak paham: catat setelan awal sebelum diubah.$li$, $li$Unduhan besar, streaming 4K, dan update sistem di banyak perangkat bersamaan memang memperlambat jaringan — ini normal, bukan kerusakan.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Setelah ketiga langkah, ulangi tes kecepatan di lokasi yang dulu bermasalah. Jika kecepatan sudah mendekati paket langganan, masalah selesai. Jika tetap lambat bahkan di dekat router dengan kabel LAN, hubungi penyedia internet dan tunjukkan hasil tesmu sebagai bukti. Jika hanya satu ruangan yang bermasalah, pertimbangkan repeater atau mesh WiFi sebagai solusi jangka panjang.$txt$));
INSERT INTO madevi.articles (id, business_code, title, slug, summary, status, language, attribution_type, taxonomy_node_id, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Luka Kecil yang Sangat Mengganggu$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Sariawan adalah luka kecil berwarna putih kekuningan dengan tepi kemerahan di dalam mulut — di bibir dalam, lidah, pipi bagian dalam, atau gusi. Rasanya perih terutama saat makan makanan asam, pedas, atau panas, dan saat menyikat gigi. Kebanyakan sariawan sembuh sendiri dalam 7-14 hari, tapi ada langkah yang bisa mempercepat penyembuhan dan mengurangi rasa sakit.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan Penyebab dan Persiapan Perawatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Penyebab pasti sariawan ringan (stomatitis aftosa) belum sepenuhnya diketahui, tetapi pemicunya jelas: tergigit saat mengunyah, luka dari sikat gigi yang kasar, stres, kurang tidur, kekurangan vitamin B12, zat besi, atau asam folat, perubahan hormon, dan makanan tertentu. Sistem kekebalan tubuh bereaksi berlebihan di titik luka kecil itu sehingga terbentuk ulkus. Sariawan bukan herpes bibir dan tidak menular.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 4, jsonb_build_object('items', to_jsonb(ARRAY[$li$Air hangat dan garam dapur untuk kumur$li$, $li$Sikat gigi berbulu lembut$li$, $li$Es batu kecil untuk meredakan nyeri$li$, $li$Obat oles sariawan bebas bila perlu$li$, $li$Hindari obat kumur beralkohol karena memperparah perih$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 5, jsonb_build_object('text', $txt$Langkah 1-3: Perawatan di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 6, jsonb_build_object('items', to_jsonb(ARRAY[$li$Sikat gigi dua kali sehari dengan sikat berbulu lembut, hindari menyentuh luka secara langsung.$li$, $li$Berkumur dengan air garam hangat (setengah sendok teh garam dalam segelas air) 2-3 kali sehari setelah makan.$li$, $li$Hindari pasta gigi yang mengandung sodium lauryl sulfate (SLS) jika sariawan sering kambuh.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Atur pola makan: pilih makanan lembut dan tidak panas seperti bubur, sup hangat, dan yogurt; hindari yang pedas, asam (jeruk, nanas), keripik, dan minuman bersoda. Makan perlahan agar tidak tergigit lagi di area yang sama. Untuk meredakan nyeri, tempelkan es batu kecil pada luka beberapa menit; obat oles sariawan bebas bisa melindungi luka dari gesekan makanan — pakai sesuai petunjuk kemasan, biasanya setelah makan dan sebelum tidur. Jangan mencongkel atau menggigit luka sariawan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Kapan Harus Waspada$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Sariawan lebih besar dari 1 cm, sangat nyeri, atau tidak sembuh setelah 2 minggu.$li$, $li$Muncul berulang sangat sering (beberapa kali sebulan) atau dalam jumlah banyak sekaligus.$li$, $li$Disertai demam tinggi, sulit menelan, atau luka juga muncul di kulit.$li$, $li$Terjadi pada bayi atau orang dengan daya tahan tubuh lemah.$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Pemeriksaan Hasil dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Sariawan biasa mengecil dalam 3-5 hari dan hilang dalam 1-2 minggu. Jika tanda bahaya di atas muncul, periksakan ke dokter atau dokter gigi. Untuk pencegahan jangka panjang: kelola stres, tidur cukup, makan bergizi seimbang, dan ganti sikat gigi secara rutin. Catatan: artikel ini berisi informasi umum dan bukan pengganti nasihat medis. Jika ragu, konsultasikan ke dokter atau dokter gigi.$txt$));
INSERT INTO madevi.articles (id, business_code, title, slug, summary, status, language, attribution_type, taxonomy_node_id, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Siapa Orang Mentawai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Orang Mentawai adalah masyarakat adat yang mendiami Kepulauan Mentawai di lepas pantai barat Sumatra, Provinsi Sumatra Barat. Mereka termasuk salah satu kelompok masyarakat adat tertua di Indonesia yang hingga kini mempertahankan cara hidup tradisional: tinggal di rumah adat Uma, berburu dan meramu di hutan, dan menjalankan kepercayaan leluhur bernama Arat Sabulungan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Tato Tertua di Dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Tato Mentawai (disebut titi) diyakini sebagai salah satu tradisi tato tertua di dunia yang masih hidup. Pembuatannya menggunakan duri pohon jeruk atau bambu runcing yang dipukul dengan kayu, dengan tinta dari arang. Motifnya bukan sekadar hiasan: setiap pola menandai identitas klan, status sosial, dan perjalanan hidup seseorang — dari masa kanak-kanak hingga dewasa. Prosesnya menyakitkan dan dianggap sebagai ujian kedewasaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Arat Sabulungan dan Sikerei$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Arat Sabulungan adalah kepercayaan bahwa segala sesuatu — manusia, hewan, tumbuhan, batu, sungai — memiliki roh (simagre). Karena itu, setiap tindakan terhadap alam harus disertai doa agar roh alam tidak marah; sebelum menebang pohon atau berburu, orang Mentawai memohon izin. Sikerei, dukun sekaligus tabib adat, memimpin upacara dan menjaga pengetahuan tumbuhan obat; tato di tubuhnya biasanya paling lengkap sebagai penanda ilmunya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Kehidupan di Uma dan Tantangan Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Uma adalah rumah adat besar berbentuk panggung yang dihuni beberapa keluarga satu klan, dengan makanan pokok sagu dan gotong royong sebagai napas hidup. Sejak program pemukiman masuk pada 1970-an, banyak tradisi tertekan: tato sempat dilarang, hutan menyusut, dan generasi muda tertarik ke kota. Namun dua dekade terakhir muncul kebangkitan lewat festival budaya, ekowisata, dan dokumentasi adat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pelajaran dari Mentawai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Kearifan Mentawai mengajarkan bahwa manusia bukan penguasa alam melainkan bagian darinya. Prinsip meminta izin sebelum mengambil — yang dalam bahasa modern disebut keberlanjutan — sudah mereka praktikkan turun-temurun. Di tengah krisis iklim, cara pandang Arat Sabulungan terasa semakin relevan: menjaga hutan berarti menjaga kehidupan itu sendiri.$txt$));
INSERT INTO madevi.articles (id, business_code, title, slug, summary, status, language, attribution_type, taxonomy_node_id, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Mengenal Unsur Perak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Perak adalah unsur kimia bersimbol Ag (dari bahasa Latin argentum) dengan nomor atom 47. Ia termasuk logam mulia: mengilap, mudah dibentuk, tahan karat, dan langka. Manusia mengenal perak sejak ribuan tahun lalu — jauh sebelum besi — sehingga ia punya sejarah panjang sebagai perhiasan, uang, dan simbol kekayaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penghantar Listrik Terbaik dan Sifat Antibakteri$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Fakta yang jarang diketahui: perak adalah penghantar listrik terbaik di antara semua logam, bahkan mengalahkan tembaga dan emas. Alasan tembaga lebih dipakai untuk kabel hanyalah harga. Di komponen elektronik kelas atas — kontak sakelar dan konektor presisi — perak tetap pilihan utama. Selain itu ion perak mampu membunuh bakteri dan jamur; nanopartikel perak kini dipakai pada perban luka dan alat medis. Namun menelan perak sembarangan berbahaya dan bisa menyebabkan argiria, kulit membiru permanen.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Perak dalam Sejarah Uang$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Selama berabad-abad, perak adalah tulang punggung sistem moneter dunia. Koin perak beredar dari Romawi kuno hingga kesultanan di Nusantara. Kata "perak" dalam bahasa Indonesia bahkan menjadi sinonim uang dalam beberapa ungkapan daerah. Standar perak runtuh pada abad ke-19 hingga ke-20 ketika negara-negara beralih ke standar emas lalu uang kertas.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Perak dalam Industri Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sekitar separuh konsumsi perak dunia kini untuk industri: panel surya (pasta perak pada sel fotovoltaik), elektronik, baterai, dan katalis kimia. Setiap panel surya mengandung sedikit perak, sehingga ledakan energi terbarukan membuat permintaan perak industri terus naik. Perak juga dipakai pada kaca reflektif dan cermin berkualitas tinggi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Perak vs Emas: Menutup$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Dibanding emas, perak lebih reaktif — ia menghitam saat bereaksi dengan belerang di udara, membentuk lapisan perak sulfida, sehingga perhiasan perak perlu dibersihkan berkala. Namun justru karena lebih terjangkau, perak menjadi pintu masuk investasi logam mulia bagi banyak orang. Dari sendok di dapur, koin kuno, hingga panel surya — perak mengingatkan bahwa nilai sebuah unsur tidak hanya dari kilaunya, tetapi dari sifat yang membuatnya tak tergantikan.$txt$));
INSERT INTO madevi.articles (id, business_code, title, slug, summary, status, language, attribution_type, taxonomy_node_id, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$li$Menjelaskan latar belakang terjadinya Reformasi 1998$li$, $li$Menguraikan peristiwa penting pada Mei 1998$li$, $li$Menganalisis perubahan sistem politik Indonesia pasca-Reformasi$li$, $li$Menunjukkan sikap menghargai perjuangan demokrasi$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang: Dari Orde Baru ke Krisis$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Selama sekitar 32 tahun Indonesia dipimpin Presiden Soeharto dalam masa Orde Baru. Pembangunan ekonomi berjalan pesat, tetapi muncul masalah: kekuasaan terpusat, korupsi merajalela, kebebasan berpendapat dibatasi. Lalu pada pertengahan 1997 krisis moneter melanda Asia: rupiah anjlok dari sekitar Rp2.500 menjadi lebih dari Rp10.000 per dolar AS, harga kebutuhan pokok melambung, banyak perusahaan bangkrut. Krisis ekonomi membuka mata masyarakat bahwa masalahnya juga tata kelola negara.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Gerakan Mahasiswa dan Mei 1998$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Mahasiswa di berbagai kota menjadi motor perubahan dengan tuntutan reformasi total: pemberantasan korupsi, suksesi kepemimpinan nasional, dan demokratisasi. Pada 12 Mei 1998, empat mahasiswa Universitas Trisakti Jakarta gugur dalam aksi demonstrasi — peristiwa ini memicu kerusuhan besar 13-15 Mei 1998. Situasi tak terkendali hingga pada 21 Mei 1998 Presiden Soeharto mengundurkan diri dan menyerahkan kekuasaan kepada Wakil Presiden B.J. Habibie.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Perubahan Setelah Reformasi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$li$Amandemen UUD 1945: masa jabatan presiden dibatasi maksimal dua periode$li$, $li$Kebebasan pers dan berpendapat dijamin; partai politik boleh berdiri bebas$li$, $li$Desentralisasi: otonomi daerah memberi kewenangan luas kepada pemerintah daerah$li$, $li$Pemilu langsung: rakyat memilih presiden dan kepala daerah secara langsung$li$, $li$Pemisahan TNI dan Polri; dwifungsi ABRI dihapus$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Makna Reformasi bagi Kita$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Reformasi membuktikan bahwa perubahan besar bisa lahir dari keberanian warga negara — terutama generasi muda — yang menuntut keadilan dengan cara damai. Namun demokrasi harus dijaga setiap hari dengan partisipasi, sikap kritis, dan kejujuran. Sebagai pelajar, kamu bisa mulai dari hal kecil: berani berpendapat santun, menolak menyebar hoaks, dan ikut menjaga kebersihan demokrasi di lingkunganmu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$1. Jelaskan dua faktor penyebab Reformasi 1998! | Kunci: krisis moneter 1997 dan akumulasi masalah politik Orde Baru (korupsi, kekuasaan terpusat).$li$, $li$2. Apa yang terjadi pada 21 Mei 1998? | Kunci: Presiden Soeharto mengundurkan diri, digantikan B.J. Habibie.$li$, $li$3. Sebutkan tiga perubahan pasca-Reformasi! | Kunci: amandemen UUD 1945, kebebasan pers, otonomi daerah/pemilu langsung.$li$, $li$4. Mengapa mahasiswa menjadi motor gerakan? | Kunci: kelompok terdidik yang kritis dan berani menyuarakan aspirasi rakyat.$li$, $li$5. Apa makna Reformasi bagimu sebagai pelajar? | Kunci: jawaban terbuka yang menunjukkan penghargaan pada demokrasi.$li$])));
