  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$li$Siswa dapat melakukan pengurangan bilangan sampai 100$li$, $li$Siswa memahami teknik meminjam pada pengurangan bersusun$li$, $li$Siswa dapat menyelesaikan soal cerita pengurangan$li$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Mengingat Kembali dan Pengurangan Bersusun$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pengurangan artinya mengambil sebagian dari suatu jumlah. Contoh: kamu punya 9 permen, dimakan 4, sisanya 9 - 4 = 5. Tanda pengurangan adalah (-). Hasil pengurangan disebut selisih. Cara bersusun: tulis bilangan besar di atas, pengurang di bawahnya, luruskan satuan dengan satuan dan puluhan dengan puluhan. Kurangkan dari kanan (satuan) dulu, baru puluhan. Contoh: 48 - 25. Satuan: 8 - 5 = 3. Puluhan: 4 - 2 = 2. Jadi 48 - 25 = 23.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Teknik Meminjam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Bagaimana jika angka satuan atas lebih kecil dari bawah, misalnya 53 - 28? Angka 3 tidak bisa dikurangi 8. Caranya: pinjam 1 puluhan dari angka 5, sehingga 5 menjadi 4 dan 3 menjadi 13. Sekarang 13 - 8 = 5. Puluhan: 4 - 2 = 2. Jadi 53 - 28 = 25. Ingat: yang dipinjam harus dikembalikan dengan mengurangi angka puluhannya! Contoh lain: 62 - 47 menjadi 12 - 7 = 5 dan 5 - 4 = 1, hasilnya 15.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Soal Cerita Pengurangan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Ibu membeli 85 butir telur. Sebanyak 37 butir dipakai untuk membuat kue. Berapa sisa telur ibu? Cara: 85 - 37. Satuan: 5 - 7 tidak bisa, pinjam menjadi 15 - 7 = 8. Puluhan: 7 - 3 = 4. Jadi sisa telur ibu adalah 48 butir. Tips soal cerita: cari kata kunci seperti "sisa", "diberikan", "dipakai", atau "berkurang" — itu tanda soal pengurangan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Kesalahan yang Sering Terjadi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$li$Lupa mengurangi angka puluhan setelah meminjam — ini kesalahan paling sering!$li$, $li$Satuan dan puluhan tidak lurus saat menulis bersusun$li$, $li$Mengurangi dari kiri (puluhan dulu) padahal harus dari kanan (satuan dulu)$li$, $li$Terbalik mengurangkan: 3 - 8 ditulis jadi 8 - 3$li$])));
