  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$li$1. 57 - 23 = ... | Kunci: 34$li$, $li$2. 84 - 59 = ... | Kunci: 25$li$, $li$3. 70 - 45 = ... | Kunci: 25$li$, $li$4. 96 - 28 = ... | Kunci: 68$li$, $li$5. Di kelas ada 64 buku. Dipinjam 29 buku. Berapa sisanya? | Kunci: 64 - 29 = 35 buku$li$])));
